import java.util.*;
import java.util.function.*;

// ここを変えてみよう:名前を足す / reversed() を消して短い順にする
List<String> names =
    new ArrayList<>(List.of("Mika", "Bob", "Alice", "Ken"));

// ① 匿名クラス(Java 7 までの書き方)
names.sort(new Comparator<String>() {
    @Override
    public int compare(String a, String b) {
        return a.compareTo(b);
    }
});
System.out.println("① 辞書順      : " + names);

// ② ラムダ式:渡したい処理だけを書く
names.sort((a, b) -> a.length() - b.length());
System.out.println("② 短い順      : " + names);

// ③ メソッド参照 + Comparator の組み立て
names.sort(Comparator.comparing(String::length)
    .reversed()
    .thenComparing(Comparator.naturalOrder()));
System.out.println("③ 長い順→辞書順: " + names);

// 標準の関数型インターフェース
Predicate<String> isLong = s -> s.length() >= 4;
Function<String, String> shout = s -> s.toUpperCase() + "!";
Consumer<String> print = System.out::println;
Supplier<List<String>> newList = ArrayList::new;

List<String> picked = newList.get();
for (String n : names) {
    if (isLong.test(n)) {
        picked.add(shout.apply(n));
    }
}
picked.forEach(print);

import java.util.*;

class Order {
    private final String customer;
    private final int amount;
    Order(String customer, int amount) {
        this.customer = customer;
        this.amount = amount;
    }
    String getCustomer() { return customer; }
    int getAmount() { return amount; }
}

public class Main {
    public static void main(String[] args) {
        // ここを変えてみよう:5000 や limit(3) を変える / distinct() を消す
        List<Order> orders = List.of(
            new Order("Sato", 7200),
            new Order("Tanaka", 3000),
            new Order("Suzuki", 5000),
            new Order("Sato", 9800),
            new Order("Ito", 12000),
            new Order("Abe", 6400));

        List<String> top = orders.stream()      // 生成
            .filter(o -> o.getAmount() >= 5000) // 中間操作
            .map(Order::getCustomer)
            .distinct()
            .sorted()
            .limit(3)
            .toList();                          // 終端操作
        System.out.println("Stream版: " + top);

        // 同じことを for 文で
        List<String> names = new ArrayList<>();
        for (Order o : orders) {
            String c = o.getCustomer();
            boolean big = o.getAmount() >= 5000;
            if (big && !names.contains(c)) {
                names.add(c);
            }
        }
        Collections.sort(names);
        List<String> top2 =
            names.subList(0, Math.min(3, names.size()));
        System.out.println("for 版  : " + top2);

        int total = orders.stream()
            .filter(o -> o.getAmount() >= 5000)
            .mapToInt(Order::getAmount)
            .sum();
        System.out.println("5000円以上の合計: " + total + "円");
    }
}

import java.util.*;
import java.util.stream.*;

class Employee {
    private final String id;
    private final String name;
    private final String dept;
    private final int salary;
    Employee(String id, String name,
             String dept, int salary) {
        this.id = id;
        this.name = name;
        this.dept = dept;
        this.salary = salary;
    }
    String getId() { return id; }
    String getName() { return name; }
    String getDept() { return dept; }
    int getSalary() { return salary; }
}

public class Main {
    public static void main(String[] args) {
        // ここを変えてみよう:社員を足す / 部署名を "開発" 以外にしてみる
        List<Employee> emps = List.of(
            new Employee("E01", "佐藤", "開発", 420),
            new Employee("E02", "鈴木", "営業", 380),
            new Employee("E03", "田中", "開発", 510),
            new Employee("E04", "伊藤", "総務", 350),
            new Employee("E05", "渡辺", "営業", 400));

        // TreeMap で包むのはキー(部署名)順に表示するため
        Map<String, List<String>> byDept = new TreeMap<>(
            emps.stream().collect(Collectors.groupingBy(
                Employee::getDept,
                // mapping:社員を「名前だけ」に変えて集める
                Collectors.mapping(Employee::getName,
                    Collectors.toList()))));
        System.out.println("部署ごと: " + byDept);

        Map<String, Long> count = new TreeMap<>(
            emps.stream().collect(Collectors.groupingBy(
                Employee::getDept, Collectors.counting())));
        System.out.println("人数    : " + count);

        Map<String, String> idToName = emps.stream()
            .collect(Collectors.toMap(
                Employee::getId, Employee::getName));
        System.out.println("E03 は  : "
            + idToName.get("E03"));

        String csv = emps.stream()
            .map(Employee::getName)
            .collect(Collectors.joining(", "));
        System.out.println("全員    : " + csv);

        double avg = emps.stream()
            .filter(e -> e.getDept().equals("開発"))
            .mapToInt(Employee::getSalary)
            .average()
            .orElse(0);
        System.out.println("開発の平均給与: " + avg + "万円");
    }
}

import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        // ① 遅延評価:終端操作を呼ぶまで map は動かない
        Stream<String> s = Stream.of("a", "b", "c")
            .map(x -> {
                System.out.println("  map: " + x);
                return x.toUpperCase();
            });
        System.out.println("まだ何も起きていない");
        System.out.println("結果: " + s.toList());

        // ② limit は必要な分だけ流す
        // ここを変えてみよう:limit(2) を limit(5) にする
        List<Integer> evens = Stream.of(1, 2, 3, 4, 5, 6)
            .filter(n -> {
                System.out.println("  filter: " + n);
                return n % 2 == 0;
            })
            .limit(2)
            .toList();
        System.out.println("偶数を2つ: " + evens);

        // ③ Stream は使い切り
        try {
            s.count();   // ① の s をもう一度使う
        } catch (IllegalStateException e) {
            System.out.println("再利用エラー: " + e.getMessage());
        }

        // ④ ラムダから外のローカル変数は書き換えられない
        int base = 100;          // 実質 final(この後代入しない)
        // base = 200;           // ← コメントを外すと下の行がコンパイルエラー
        List<Integer> plus = Stream.of(1, 2, 3)
            .map(n -> n + base)
            .toList();
        System.out.println("base を足す: " + plus);
    }
}

